# VPC, subnets, firewall, and Global External Load Balancer

resource "google_compute_network" "vpc" {
  name                    = "${local.prefix}-vpc"
  project                 = local.project_id
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
}

resource "google_compute_subnetwork" "ingress" {
  name                     = "${local.prefix}-ingress-subnet"
  project                  = local.project_id
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = "10.10.0.0/20"
  private_ip_google_access = true
}

resource "google_compute_subnetwork" "private" {
  name                     = "${local.prefix}-private-subnet"
  project                  = local.project_id
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = "10.10.16.0/20"
  private_ip_google_access = true
}

resource "google_compute_firewall" "ingress_http" {
  name    = "${local.prefix}-fw-ingress-http"
  project = local.project_id
  network = google_compute_network.vpc.id
  direction = "INGRESS"
  priority  = 1000

  allow {
    protocol = "tcp"
    ports    = ["80", "8080"]
  }

  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["mediapulse-ingress", "mediapulse-api"]
}

resource "google_compute_firewall" "db_internal" {
  name    = "${local.prefix}-fw-db-internal"
  project = local.project_id
  network = google_compute_network.vpc.id
  direction = "INGRESS"
  priority  = 1000

  allow {
    protocol = "tcp"
    ports    = ["5432"]
  }

  source_ranges = [
    google_compute_subnetwork.ingress.ip_cidr_range,
    google_compute_subnetwork.private.ip_cidr_range,
  ]
  target_tags = ["mediapulse-db"]
}

# Global external load balancer fronting the Cloud Run API via a Serverless NEG

resource "google_compute_global_address" "lb_ip" {
  name    = "${local.prefix}-lb-ip"
  project = local.project_id
}

resource "google_compute_region_network_endpoint_group" "api_neg" {
  name                  = "${local.prefix}-api-neg"
  project               = local.project_id
  region                = local.region
  network_endpoint_type = "SERVERLESS"

  cloud_run {
    service = google_cloud_run_v2_service.api.name
    region   = local.region
  }
}

resource "google_compute_backend_service" "api_backend" {
  name                  = "${local.prefix}-api-backend"
  project               = local.project_id
  protocol              = "HTTPS"
  load_balancing_scheme = "EXTERNAL_MANAGED"
  session_affinity      = "NONE"
  timeout_sec           = 60

  backend {
    group           = google_compute_region_network_endpoint_group.api_neg.id
    capacity_scaler = 1.0
  }
}

resource "google_compute_url_map" "api_url_map" {
  name            = "${local.prefix}-api-url-map"
  project         = local.project_id
  default_service = google_compute_backend_service.api_backend.id
}

resource "google_compute_target_http_proxy" "api_proxy" {
  name    = "${local.prefix}-api-http-proxy"
  project = local.project_id
  url_map = google_compute_url_map.api_url_map.id
}

resource "google_compute_global_forwarding_rule" "api_fr" {
  name       = "${local.prefix}-api-fr"
  project    = local.project_id
  target     = google_compute_target_http_proxy.api_proxy.id
  ip_address = google_compute_global_address.lb_ip.address
  port_range = "80"
}

# Cloud KMS CMEK keys

resource "google_kms_key_ring" "ring" {
  name     = "${local.prefix}-keyring"
  project  = local.project_id
  location = local.region
}

resource "google_kms_crypto_key" "database" {
  name            = "${local.prefix}-db-key"
  key_ring        = google_kms_key_ring.ring.id
  rotation_period = "7776000s"
  purpose         = "ENCRYPT_DECRYPT"
}

resource "google_kms_crypto_key" "messaging" {
  name            = "${local.prefix}-messaging-key"
  key_ring        = google_kms_key_ring.ring.id
  rotation_period = "7776000s"
  purpose         = "ENCRYPT_DECRYPT"
}

resource "google_kms_crypto_key" "projection" {
  name            = "${local.prefix}-projection-key"
  key_ring        = google_kms_key_ring.ring.id
  rotation_period = "7776000s"
  purpose         = "ENCRYPT_DECRYPT"
}

resource "google_kms_crypto_key" "audit" {
  name            = "${local.prefix}-audit-key"
  key_ring        = google_kms_key_ring.ring.id
  rotation_period = "7776000s"
  purpose         = "ENCRYPT_DECRYPT"
}

# Cloud SQL for PostgreSQL (event store + transactional outbox)

resource "google_sql_database_instance" "main" {
  name             = "${local.prefix}-pg"
  project          = local.project_id
  region           = local.region
  database_version = "POSTGRES_16"

  settings {
    tier = "db-custom-1-3840"
    availability_type = "ZONAL"

    disk_encryption_configuration {
      kms_key_name = google_kms_crypto_key.database.id
    }

    ip_configuration {
      ipv4_enabled = false
      private_network = "projects/${local.project_id}/global/networks/${google_compute_network.vpc.name}"
    }
  }
}

resource "google_sql_database" "db" {
  name     = local.db_name
  project  = local.project_id
  instance = google_sql_database_instance.main.name
}

resource "google_sql_user" "user" {
  name     = local.db_username
  project  = local.project_id
  instance = google_sql_database_instance.main.name
  password = local.db_password
}

locals {
  db_host        = coalesce(google_sql_database_instance.main.private_ip_address, "gcp")
  database_url   = "postgresql://${local.db_username}:${urlencode(local.db_password)}@${local.db_host}:5432/${local.db_name}?sslmode=disable"
}

# Secret Manager - database connection string

resource "google_secret_manager_secret" "db_url" {
  name      = "${local.prefix}-db-url"
  project   = local.project_id
  labels    = local.common_labels

  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_version" "db_url" {
  secret      = google_secret_manager_secret.db_url.id
  secret_data = local.database_url
}

resource "google_secret_manager_secret" "db_password" {
  name      = "${local.prefix}-db-password"
  project   = local.project_id
  labels    = local.common_labels

  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_version" "db_password" {
  secret      = google_secret_manager_secret.db_password.id
  secret_data = local.db_password
}

# Cloud Pub/Sub - main topic, push subscription, dead-letter

resource "google_pubsub_topic" "main" {
  name    = "${local.prefix}-events"
  project = local.project_id
  labels  = local.common_labels

  kms_key_name = google_kms_crypto_key.messaging.id
}

resource "google_pubsub_topic" "dlq" {
  name    = "${local.prefix}-events-dlq"
  project = local.project_id
  labels  = local.common_labels
}

resource "google_pubsub_subscription" "processor_push" {
  name    = "${local.prefix}-processor-push"
  project = local.project_id
  topic   = google_pubsub_topic.main.id
  labels  = local.common_labels

  ack_deadline_seconds = 60

  push_config {
    push_endpoint = google_cloudfunctions2_function.processor.service_config[0].uri

    oidc_token {
      service_account_email = google_service_account.processor.email
    }
  }

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dlq.id
    max_delivery_attempts = 5
  }

  retry_policy {
    minimum_backoff = "10s"
    maximum_backoff = "600s"
  }
}

resource "google_pubsub_subscription" "dlq" {
  name    = "${local.prefix}-events-dlq-sub"
  project = local.project_id
  topic   = google_pubsub_topic.dlq.id
  labels  = local.common_labels

  ack_deadline_seconds = 600
}

# Cloud Tasks queue for projection rebuilds

resource "google_cloud_tasks_queue" "rebuild" {
  name    = "${local.prefix}-rebuild-queue"
  project = local.project_id
  location = local.region

  rate_limits {
    max_concurrent_dispatches = 20
    max_dispatches_per_second  = 50
  }
}

# Cloud Firestore (native) projections + MediaCache index

resource "google_firestore_database" "main" {
  name        = "(default)"
  project     = local.project_id
  location_id = local.region
  type        = "FIRESTORE_NATIVE"

  # Point-in-time recovery optional; enable for durability
  point_in_time_recovery_enable = false
}

resource "google_firestore_index" "mediacache" {
  project    = local.project_id
  database   = google_firestore_database.main.name
  collection = "MediaCache"

  fields {
    field_path = "ownerId"
    order      = "ASCENDING"
  }

  fields {
    field_path = "updatedAt"
    order      = "DESCENDING"
  }
}

resource "google_firestore_index" "media_projections" {
  project    = local.project_id
  database   = google_firestore_database.main.name
  collection = "media_projections"

  fields {
    field_path = "ownerId"
    order      = "ASCENDING"
  }

  fields {
    field_path = "aggregateVersion"
    order      = "DESCENDING"
  }
}

# GCS audit bucket + BigQuery audit dataset

resource "google_storage_bucket" "audit" {
  name          = "${local.prefix}-audit-logs"
  project       = local.project_id
  location      = "US-EAST1"
  force_destroy = true

  public_access_prevention = "enforced"

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = google_kms_crypto_key.audit.id
  }

  uniform_bucket_level_access = true
}

resource "google_bigquery_dataset" "audit" {
  dataset_id = "${replace(local.prefix, "-", "_")}_audit"
  project    = local.project_id
  location   = "US"

  default_table_expiration_ms = 0
}

resource "google_bigquery_table" "audit_events" {
  project    = local.project_id
  dataset_id = google_bigquery_dataset.audit.dataset_id
  table_id   = "audit_events"

  schema = jsonencode([
    { name = "eventId",       type = "STRING", mode = "REQUIRED" },
    { name = "eventType",     type = "STRING", mode = "REQUIRED" },
    { name = "aggregateId",   type = "STRING", mode = "REQUIRED" },
    { name = "aggregateVersion", type = "INTEGER", mode = "REQUIRED" },
    { name = "ownerId",        type = "STRING", mode = "REQUIRED" },
    { name = "occurredAt",     type = "TIMESTAMP", mode = "REQUIRED" },
    { name = "correlationId",  type = "STRING" },
    { name = "batch",          type = "STRING" },
  ])
}

# Cloud Run (v2) API service

resource "google_cloud_run_v2_service" "api" {
  name     = "${local.prefix}-api"
  project  = local.project_id
  location = local.region

  ingress = "INGRESS_ALL"

  template {
    service_account = google_service_account.api.email
    max_instance_request_concurrency = 100

    scaling {
      min_instance_count = 2
      max_instance_count = 10
    }

    containers {
      image = local.cfg.api_image
      name  = "api"
      ports {
        container_port = 8080
      }

      env {
        name  = "DATABASE_URL"
        value = local.database_url
      }
      env {
        name  = "DATASTORE_NAMESPACE"
        value = local.datastore_namespace
      }
      env {
        name  = "FIREBASE_AUTH_JWKS_URL"
        value = "${local.gcp_endpoint}/robot/v1/metadata/jwk/securetoken@system.gserviceaccount.com"
      }
      env {
        name  = "GOOGLE_CLOUD_PROJECT"
        value = local.project_id
      }
      env {
        name  = "PUBSUB_TOPIC"
        value = google_pubsub_topic.main.name
      }
      env {
        name  = "FIRESTORE_DATABASE"
        value = google_firestore_database.main.name
      }
    }
  }
}

