  project   = local.project_id
  labels    = local.common_labels

  replication {
    auto {}
  }
}

arguments.newString:
output "logs_api" { value = google_logging_project_bucket_config.main.bucket_id }
output "logs_processor" { value = google_logging_project_bucket_config.main.bucket_id }
output "logs_relay" { value = google_logging_project_bucket_config.main.bucket_id }
output "logs_archiver" { value = google_logging_project_bucket_config.main.bucket_id }

arguments.oldString:
output "logs_api" { value = google_logging_project_bucket_config.main.name }
output "logs_processor" { value = google_logging_project_bucket_config.main.name }
output "logs_relay" { value = google_logging_project_bucket_config.main.name }
output "logs_archiver" { value = google_logging_project_bucket_config.main.name }

arguments.newString:
resource "google_identity_platform_tenant" "main" {
  provider     = google-beta
  project      = local.project_id
  display_name = "MediaPulse Ingest tenants"
}

  dataset_id = "${replace(local.prefix, "-", "_")}_audit"
  project    = local.project_id
  location   = "US"

  default_encryption_configuration {
    kms_key = google_kms_crypto_key.audit.id
  }
}
